        <div className="space-y-2">
          <p className="text-xs font-bold text-gray-700 uppercase tracking-wide">
            {L('Pick a reason', 'కారణం ఎంచుకోండి')}
          </p>
          <div className="grid grid-cols-2 gap-2">
            {DECLINE_PRESETS.map((preset) => (
              <button
                key={preset}
