  total_price: number | null
  buyer_name: string | null
  buyer_phone: string | null
  pickup_location: string | null
  status: 'pending' | 'approved' | 'declined' | 'cancelled'
  payment_status: string | null
  decline_reason: string | null
  refund_status: string | null
  refund_amount: number | null
  refunded_at: string | null
  delivery_type: 'self_pickup' | 'home_delivery' | 'courier' | null
  collected_at: string | null
  shipped_at: string | null
  received_at: string | null
  fulfillment_date: string | null
  created_at: string
  acknowledged_at: string | null
}

type Filter = 'today' | 'week' | 'month'

export default function OrderHistoryPage() {
  const router = useRouter()
  const { tx, L } = useLang()
  const [orders, setOrders] = useState<Order[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<Filter>('week')

  const load = useCallback(async () => {
    const farmerId = localStorage.getItem('yff_farmer_id')
    if (!farmerId) { router.replace('/farmer/login'); return }

    setLoading(true)
    // Explicit columns: handover_otp is deliberately NOT fetched — the pickup
    // code must come from the customer, so the farmer's browser never sees it.
    const { data } = await supabase
      .from('orders')
      .select('id, farmer_id, order_code, produce_listing_id, produce_name, quantity, unit, total_price, buyer_name, buyer_phone, pickup_location, status, payment_status, decline_reason, refund_status, refund_amount, refunded_at, delivery_type, collected_at, shipped_at, received_at, fulfillment_date, created_at, acknowledged_at')
      .eq('farmer_id', farmerId)
      // Approved, declined, and buyer-cancelled orders the farmer has already
      // acknowledged. An unacknowledged cancellation is still in the active
      // dashboard awaiting the farmer's Acknowledge tap, so it's excluded here.
      .or('status.eq.approved,status.eq.declined,and(status.eq.cancelled,acknowledged_at.not.is.null)')
      .order('created_at', { ascending: false })

    setOrders((data ?? []) as Order[])
    setLoading(false)
  }, [router])

  useEffect(() => { load() }, [load])

  // Farmer sets/updates the pickup-or-delivery date on an approved order.
  const setFulfillmentDate = async (orderId: string, date: string) => {
    const value = date || null
    setOrders((prev) => prev.map((o) => (o.id === orderId ? { ...o, fulfillment_date: value } : o)))
    await supabase.from('orders').update({ fulfillment_date: value }).eq('id', orderId)
  }

  const filterStart = () => {
    if (filter === 'today') {
      const d = new Date()
      d.setHours(0, 0, 0, 0)
      return d.getTime()
    }
    if (filter === 'week') return Date.now() - 7 * 86400000
    return Date.now() - 30 * 86400000
  }

  const filtered = orders.filter((o) => new Date(o.created_at).getTime() >= filterStart())
  const revenue = filtered
    .filter((o) => o.status === 'approved')
    .reduce((sum, o) => sum + (o.total_price ?? 0), 0)

  return (
    <main className="min-h-screen bg-gray-50 pb-16">
      {/* Header */}
      <div className="bg-green-900 px-4 pt-6 pb-10">
        <Link href="/farmer/dashboard" className="text-green-300 text-sm flex items-center gap-1 mb-4">
          ← {tx.back}
        </Link>
        <h1 className="text-white text-xl font-extrabold leading-tight">
          {tx.orderHistory}
        </h1>
        <p className="text-green-400 text-sm mt-1">Approved &amp; declined orders</p>
      </div>

      <div className="px-4 -mt-5 space-y-4">
        {/* Filter pills */}
        <div className="bg-white rounded-2xl border border-gray-100 p-3 flex gap-2">
          {(['today', 'week', 'month'] as const).map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`flex-1 py-2.5 rounded-xl text-xs font-bold transition-colors ${
                filter === f ? 'bg-green-700 text-white' : 'bg-gray-100 text-gray-600 active:bg-gray-200'
              }`}
            >
              {f === 'today' ? tx.filterToday : f === 'week' ? tx.filterWeek : tx.filterMonth}
            </button>
          ))}
        </div>

        {/* Revenue summary */}
        {revenue > 0 && (
          <div className="bg-green-50 border border-green-200 rounded-2xl p-4 flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold text-green-700 uppercase tracking-wide">
                {tx.totalRevenue}
              </p>
              <p className="text-3xl font-black text-green-800 mt-0.5">₹{revenue}</p>
            </div>
            <div className="text-4xl">💰</div>
          </div>
        )}

        {/* Order list */}
        {loading ? (
          <div className="text-center py-16">
            <div className="w-10 h-10 border-4 border-green-700 border-t-transparent rounded-full animate-spin mx-auto" />
            <p className="text-gray-500 text-sm mt-3">{tx.loadingLabel}</p>
          </div>
        ) : filtered.length === 0 ? (
          <div className="text-center py-16">
            <div className="text-5xl mb-3">📭</div>
            <p className="font-semibold text-gray-500 text-sm">{tx.noPendingOrders}</p>
          </div>
        ) : (
          <div className="space-y-3">
            {filtered.map((order) => (
              <HistoryCard
                key={order.id}
                order={order}
                onSetDate={(d) => setFulfillmentDate(order.id, d)}
              />
            ))}
          </div>
        )}
      </div>
    </main>
  )
}

function HistoryCard({ order, onSetDate }: { order: Order; onSetDate: (date: string) => void }) {
  const { tx, L } = useLang()
  const isApproved = order.status === 'approved'
  const isCancelled = order.status === 'cancelled'
  const isDelivery = order.delivery_type === 'home_delivery'
  const isCourier = order.delivery_type === 'courier'

  const timeStr = new Date(order.created_at).toLocaleDateString('en-IN', {
    day: 'numeric',
    month: 'short',
    hour: '2-digit',
    minute: '2-digit',
  })

  const stamp = (iso: string | null) =>
    iso ? new Date(iso).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : ''

  // Completion line for an approved order: the final milestone + its date.
  // Shipped flow (courier + farmer-shipped home delivery): Received (done) ▸
  // Shipped (in transit). Pickup: Picked up.
  const isShippedFlow = isCourier || isDelivery
  const completion = !isApproved ? null
    : isShippedFlow
      ? order.received_at
        ? { text: `${L('✓ Received', '✓ అందుకున్నారు')} · ${stamp(order.received_at)}`, cls: 'text-green-700' }
        : order.shipped_at
          ? { text: `${L('🚚 Shipped', '🚚 షిప్ చేయబడింది')} · ${stamp(order.shipped_at)}`, cls: 'text-amber-700' }
          : null
      : order.collected_at
        ? { text: `${L('✓ Picked up', '✓ తీసుకువెళ్ళారు')} · ${stamp(order.collected_at)}`, cls: 'text-green-700' }
        : null

  return (
    <div className={`rounded-2xl border overflow-hidden ${isApproved ? 'border-green-200 bg-white' : 'border-gray-200 bg-gray-50'}`}>
      <div className="p-3 space-y-1.5">
        <div className="flex items-start justify-between gap-2">
          <div className="min-w-0">
            <div className="flex items-center gap-2 flex-wrap">
              <p className="font-extrabold text-gray-900 text-sm leading-tight">
                {order.buyer_name || '—'}
              </p>
              <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                isApproved ? 'bg-green-100 text-green-800'
                  : isCancelled ? 'bg-gray-200 text-gray-700'
                  : 'bg-red-100 text-red-700'
              }`}>
                {isApproved ? tx.statusApproved
                  : isCancelled ? L('Cancelled by buyer', 'కొనుగోలుదారు రద్దు చేశారు')
                  : tx.statusDeclined}
              </span>
            </div>
            {order.buyer_phone && (
              <a href={`tel:+91${order.buyer_phone}`} className="text-xs font-semibold text-green-700">
                📞 +91 {order.buyer_phone}
              </a>
            )}
          </div>
          <div className="flex flex-col items-end flex-shrink-0 mt-0.5">
            <span className="text-[11px] text-gray-400 whitespace-nowrap">
              {timeStr}
            </span>
            {order.order_code && (
              <span className="text-[10px] font-mono font-semibold text-gray-400 whitespace-nowrap">
                {order.order_code}
              </span>
            )}
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-1.5 text-sm">
          <span className="font-semibold text-gray-800">{order.produce_name || '—'}</span>
          <span className="text-gray-300">·</span>
          <span className="text-gray-600">{order.quantity} {order.unit || 'kg'}</span>
          {order.total_price != null && order.total_price > 0 && (
            <>
              <span className="text-gray-300">·</span>
              <span className="font-bold text-green-700">₹{order.total_price}</span>
            </>
          )}
        </div>

        {order.pickup_location && (
          <p className="text-xs text-gray-500">📍 {order.pickup_location}</p>
        )}

        {/* Completion status + date (picked up / shipped / received). */}
        {completion && (
          <p className={`text-xs font-bold ${completion.cls}`}>{completion.text}</p>
        )}

        {/* Approved orders: farmer sets/edits the pickup-or-delivery date. */}
        {isApproved && (
          <div className="pt-1">
            <label className="text-[11px] font-bold text-gray-600 block mb-1">
              📅 {isDelivery ? tx.deliveryDateLabel : tx.pickupDateLabel}
            </label>
            <input
              type="date"
              value={order.fulfillment_date ?? ''}
              onChange={(e) => onSetDate(e.target.value)}
              className="w-full border border-gray-200 rounded-xl px-3 py-2 text-sm bg-white focus:border-green-500 focus:outline-none"
            />
          </div>
        )}

        {/* Declined orders: show the reason and the refund status to the farmer */}
        {!isApproved && order.decline_reason && (
          <p className="text-xs text-gray-600 leading-snug">
            <span className="font-semibold">{L('Reason', 'కారణం:')}</span> {order.decline_reason}
          </p>
        )}
        {!isApproved && (order.refund_status || (order.refund_amount ?? 0) > 0) && (
          <div className="mt-1 bg-green-50 border border-green-200 rounded-lg px-2.5 py-1.5">
            <p className="text-xs font-bold text-green-800 flex items-center gap-1">
              {L('💸 Refund initiated to customer', 'రీఫండ్ ప్రారంభమైంది')}
            </p>
            <p className="text-[11px] text-gray-600 leading-snug mt-0.5">
              ₹{order.refund_amount ?? order.total_price ?? 0} · reflects in 3–5 business days
              {order.refunded_at && (
                <> · {new Date(order.refunded_at).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}</>
              )}
            </p>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useLang } from '@/lib/LanguageContext'

type Review = {
  id: string
  reviewer_name: string
  reviewer_location?: string
  star_rating: number
  review_text?: string
  produce_ordered?: string
  created_at: string
}

export default function ReviewsTab({
  reviews: initialReviews,
  farmerId,
}: {
  reviews: Record<string, unknown>[]
  farmerId: string
}) {
  const { tx, L } = useLang()
  const [reviews, setReviews] = useState<Review[]>(initialReviews as Review[])
  const [showForm, setShowForm] = useState(false)
  const [name, setName] = useState('')
  const [phone, setPhone] = useState('')
  const [rating, setRating] = useState(0)
  const [hoverRating, setHoverRating] = useState(0)
  const [reviewText, setReviewText] = useState('')
  const [produceBought, setProduceBought] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState('')
  const [done, setDone] = useState(false)

  // Restore already-reviewed state from localStorage on mount
  useEffect(() => {
    if (localStorage.getItem(`yff_reviewed_${farmerId}`)) setDone(true)
  }, [farmerId])

  const avg =
    reviews.length > 0
      ? reviews.reduce((sum, r) => sum + r.star_rating, 0) / reviews.length
      : 0

  const counts = [5, 4, 3, 2, 1].map((star) => ({
    star,
    count: reviews.filter((r) => r.star_rating === star).length,
  }))

  const resetForm = () => {
    setName('')
    setPhone('')
    setRating(0)
    setHoverRating(0)
    setReviewText('')
    setProduceBought('')
    setError('')
  }

  const handleSubmit = async () => {
    if (!name.trim() || phone.replace(/\D/g, '').length < 10 || rating === 0) {
      setError(tx.reviewRequiredFields)
      return
    }
    setSubmitting(true)
    setError('')

    const res = await fetch('/api/reviews', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        farmer_id: farmerId,
        reviewer_name: name.trim(),
        reviewer_phone: phone.replace(/\D/g, '').slice(-10),
        star_rating: rating,
        review_text: reviewText.trim() || null,
        produce_ordered: produceBought.trim() || null,
      }),
    })

    const json = await res.json().catch(() => ({}))
    setSubmitting(false)

    if (res.status === 409 || json.error === 'already_reviewed') {
      localStorage.setItem(`yff_reviewed_${farmerId}`, '1')
      setDone(true)
      setShowForm(false)
      resetForm()
      return
    }

    if (!res.ok) {
      setError(json.error ?? tx.reviewError)
      return
    }

    if (json.review) setReviews((prev) => [json.review as Review, ...prev])
    localStorage.setItem(`yff_reviewed_${farmerId}`, '1')
    setDone(true)
    setShowForm(false)
    resetForm()
  }

  return (
    <div className="space-y-4">
      {/* CTA / success */}
      {done ? (
        <div className="bg-green-50 border border-green-200 rounded-xl p-4 text-center">
          <div className="text-3xl mb-1">⭐</div>
          <p className="font-bold text-green-800 text-sm">{tx.reviewSubmitted}</p>
        </div>
      ) : !showForm ? (
        <button
          onClick={() => setShowForm(true)}
          className="w-full bg-green-700 text-white font-bold py-3.5 rounded-xl text-sm active:bg-green-800"
        >
          ✏️ {tx.writeReview}
        </button>
      ) : (
        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
          <div className="flex items-center justify-between px-4 py-3 border-b border-gray-100 bg-gray-50">
            <h3 className="font-extrabold text-gray-900 text-sm">{tx.writeReview}</h3>
            <button
              onClick={() => { setShowForm(false); resetForm() }}
              className="text-gray-400 text-2xl leading-none p-1"
            >
              ×
            </button>
          </div>

          <div className="p-4 space-y-4">
            {/* Star picker */}
            <div>
              <label className="text-xs font-bold text-gray-600 uppercase tracking-wide block mb-2">
                {tx.starRatingLabel}
              </label>
              <div className="flex gap-1">
                {[1, 2, 3, 4, 5].map((s) => (
                  <button
                    key={s}
                    onClick={() => setRating(s)}
                    onMouseEnter={() => setHoverRating(s)}
                    onMouseLeave={() => setHoverRating(0)}
                    className="text-4xl leading-none transition-transform active:scale-110"
                    aria-label={`${s} stars`}
                  >
                    <span className={(hoverRating || rating) >= s ? 'text-yellow-400' : 'text-gray-200'}>
                      ★
                    </span>
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="text-xs font-bold text-gray-600 uppercase tracking-wide block mb-1.5">
                {tx.reviewerNameLabel}
              </label>
              <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Ramya"
                className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:border-green-500 focus:outline-none"
              />
            </div>

            <div>
              <label className="text-xs font-bold text-gray-600 uppercase tracking-wide block mb-1.5">
                {tx.reviewerPhoneLabel}
              </label>
              <div className="flex gap-2">
                <span className="flex items-center px-3 bg-gray-50 border border-gray-200 rounded-xl text-sm text-gray-600 font-medium">
                  +91
                </span>
                <input
                  type="tel"
                  inputMode="numeric"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                  placeholder="9876543210"
                  maxLength={10}
                  className="flex-1 border border-gray-200 rounded-xl px-4 py-3 text-sm focus:border-green-500 focus:outline-none"
                />
              </div>
              <p className="text-[11px] text-gray-400 mt-1">{L('Used only to verify your review.', 'సమీక్షను ధృవీకరించడానికి మాత్రమే.')}</p>
            </div>

            <div>
              <label className="text-xs font-bold text-gray-600 uppercase tracking-wide block mb-1.5">
                {tx.produceOrderedLabel}
              </label>
              <input
                type="text"
                value={produceBought}
                onChange={(e) => setProduceBought(e.target.value)}
                placeholder="e.g. Tomato, Brinjal"
                className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:border-green-500 focus:outline-none"
              />
            </div>

            <div>
              <label className="text-xs font-bold text-gray-600 uppercase tracking-wide block mb-1.5">
                {tx.reviewTextLabel}
              </label>
              <textarea
                value={reviewText}
                onChange={(e) => setReviewText(e.target.value.slice(0, 400))}
                placeholder="Share your experience with this farmer..."
                rows={3}
                className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm resize-none focus:border-green-500 focus:outline-none"
              />
              <p className="text-right text-xs text-gray-400">{reviewText.length}/400</p>
            </div>

            {error && (
              <p className="text-sm text-red-600 bg-red-50 rounded-xl px-3 py-2">{error}</p>
            )}

            <div className="flex gap-3">
              <button
                onClick={() => { setShowForm(false); resetForm() }}
                className="flex-1 border-2 border-gray-200 text-gray-600 font-semibold py-3 rounded-xl text-sm"
              >
                {tx.cancelBtn}
              </button>
              <button
                onClick={handleSubmit}
                disabled={submitting}
                className="flex-1 bg-green-700 text-white font-bold py-3 rounded-xl text-sm disabled:opacity-50 active:bg-green-800"
              >
                {submitting ? tx.submittingReview : tx.submitReview}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Rating summary */}
      {reviews.length > 0 && (
        <div className="bg-white rounded-xl border border-gray-100 p-4">
          <div className="flex items-center gap-4">
            <div className="text-center">
              <p className="text-4xl font-bold text-gray-900">{avg.toFixed(1)}</p>
              <div className="flex justify-center mt-1">
                {[1, 2, 3, 4, 5].map((s) => (
                  <span key={s} className={`text-base ${s <= Math.round(avg) ? 'text-yellow-400' : 'text-gray-200'}`}>
                    ★
                  </span>
                ))}
              </div>
              <p className="text-xs text-gray-500 mt-1">{reviews.length} {tx.reviews}</p>
            </div>
            <div className="flex-1 space-y-1">
              {counts.map(({ star, count }) => (
                <div key={star} className="flex items-center gap-2">
                  <span className="text-xs text-gray-500 w-3">{star}</span>
                  <div className="flex-1 bg-gray-100 rounded-full h-2">
                    <div
                      className="bg-yellow-400 h-2 rounded-full"
                      style={{ width: reviews.length ? `${(count / reviews.length) * 100}%` : '0%' }}
                    />
                  </div>
                  <span className="text-xs text-gray-500 w-4">{count}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {reviews.length === 0 && !showForm && !done && (
        <div className="text-center py-8 text-gray-400 text-sm">{tx.noReviews}</div>
      )}

      {/* Individual reviews */}
      {reviews.length > 0 && (
        <div className="space-y-3">
          {reviews.map((review) => (
            <div key={review.id} className="bg-white rounded-xl border border-gray-100 p-4">
              <div className="flex items-start justify-between gap-2">
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-full bg-green-100 flex items-center justify-center text-green-800 font-bold text-sm flex-shrink-0">
                    {review.reviewer_name.slice(0, 2).toUpperCase()}
                  </div>
                  <div>
                    <p className="text-sm font-semibold text-gray-900">{review.reviewer_name}</p>
                    {review.reviewer_location && (
                      <p className="text-xs text-gray-500">{review.reviewer_location}</p>
                    )}
                  </div>
                </div>
                <div className="text-right flex-shrink-0">
                  <div className="flex justify-end">
                    {[1, 2, 3, 4, 5].map((s) => (
                      <span key={s} className={`text-sm ${s <= review.star_rating ? 'text-yellow-400' : 'text-gray-200'}`}>
                        ★
                      </span>
                    ))}
                  </div>
                  <p className="text-[10px] text-gray-400 mt-0.5">
                    {new Date(review.created_at).toLocaleDateString('en-IN', {
                      day: 'numeric',
                      month: 'short',
                      year: 'numeric',
                    })}
                  </p>
                </div>
              </div>
              {review.review_text && (
                <p className="text-sm text-gray-600 mt-3 leading-relaxed">{review.review_text}</p>
              )}
              {review.produce_ordered && (
                <p className="text-xs text-green-700 font-semibold mt-2">
                  {tx.bought} {review.produce_ordered}
                </p>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

function admin() {
  return createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!)
}

// Recompute and cache a listing's rating aggregate after a review changes.
async function refreshAggregate(supabase: ReturnType<typeof admin>, listingId: string) {
  const { data: rows } = await supabase
    .from('produce_reviews')
    .select('star_rating')
    .eq('produce_listing_id', listingId)
    .eq('approved', true)
  const count = rows?.length ?? 0
  const avg = count > 0
    ? Math.round((rows!.reduce((s, r: { star_rating: number }) => s + r.star_rating, 0) / count) * 10) / 10
    : null
  await supabase
    .from('produce_listings')
    .update({ rating_avg: avg, review_count: count })
    .eq('id', listingId)
}

// GET /api/produce-reviews?listing_id=<uuid>
// Public — returns approved reviews + aggregate for a produce listing.
export async function GET(req: NextRequest) {
  const listingId = new URL(req.url).searchParams.get('listing_id') ?? ''
  if (!UUID_RE.test(listingId)) {
    return NextResponse.json({ error: 'Invalid listing id.' }, { status: 400 })
  }

  const supabase = admin()
  const { data: reviews, error } = await supabase
    .from('produce_reviews')
    .select('id, reviewer_name, star_rating, review_text, created_at')
    .eq('produce_listing_id', listingId)
    .eq('approved', true)
    .order('created_at', { ascending: false })
    .limit(100)

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })

  const count = reviews?.length ?? 0
  const avg = count > 0
    ? Math.round((reviews!.reduce((s, r) => s + r.star_rating, 0) / count) * 10) / 10
    : null

  return NextResponse.json({ reviews: reviews ?? [], rating_avg: avg, review_count: count })
}

// POST /api/produce-reviews
// Verified buyer leaves a review on a produce they ordered, once the order is
// delivered / picked up. Body: { order_id, star_rating, review_text? }.
export async function POST(req: NextRequest) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Login required.' }, { status: 401 })

  let body: { order_id?: unknown; star_rating?: unknown; review_text?: unknown }
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid request.' }, { status: 400 })
  }

  const orderId = typeof body.order_id === 'string' ? body.order_id : ''
  if (!UUID_RE.test(orderId)) {
    return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })
  }
  const rating = typeof body.star_rating === 'number' ? body.star_rating : NaN
  if (!Number.isInteger(rating) || rating < 1 || rating > 5) {
    return NextResponse.json({ error: 'Rating must be 1-5.' }, { status: 400 })
  }
  const text = typeof body.review_text === 'string' ? body.review_text.trim().slice(0, 600) : ''

  const supabase = admin()

  const { data: order, error: orderErr } = await supabase
    .from('orders')
    .select('id, consumer_id, produce_listing_id, farmer_id, buyer_name, buyer_phone, status, received_at, collected_at, delivered_at, delivery_status')
    .eq('id', orderId)
    .maybeSingle()

  if (orderErr) return NextResponse.json({ error: orderErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.consumer_id !== session.consumerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  if (!order.produce_listing_id) {
    return NextResponse.json({ error: 'This order cannot be reviewed.' }, { status: 400 })
  }

  // A buyer may give feedback on any of their own orders. Only feedback on a
  // *completed* order (delivered / picked up / received) is published publicly
  // and counts toward the produce's star average — that's a verified-buyer
  // rating. Feedback on a declined / cancelled / still-pending order is private
  // (approved = false): it's the buyer telling us about their experience, and is
  // never shown on the produce card so it can't unfairly drag the rating down.
  const completed =
    order.status !== 'declined' &&
    order.status !== 'cancelled' &&
    (!!order.received_at || !!order.collected_at || !!order.delivered_at || order.delivery_status === 'delivered')

  // One review per order.
  const { data: existing } = await supabase
    .from('produce_reviews')
    .select('id')
    .eq('order_id', orderId)
    .maybeSingle()
  if (existing) {
    return NextResponse.json({ error: 'already_reviewed' }, { status: 409 })
  }

  const { data: review, error: insErr } = await supabase
    .from('produce_reviews')
    .insert({
      order_id: orderId,
      produce_listing_id: order.produce_listing_id,
      farmer_id: order.farmer_id ?? null,
      consumer_id: order.consumer_id ?? null,
      reviewer_name: (order.buyer_name as string | null)?.trim()?.slice(0, 80) || 'Buyer',
      reviewer_phone: order.buyer_phone ? String(order.buyer_phone).replace(/\D/g, '').slice(-10) : null,
      star_rating: rating,
      review_text: text || null,
      approved: completed,
    })
    .select('id, reviewer_name, star_rating, review_text, created_at')
    .single()

  if (insErr) return NextResponse.json({ error: insErr.message }, { status: 500 })

  // Private (non-completed) feedback never affects the public average, so only
  // recompute the aggregate when a completed order added a public rating.
  if (completed) await refreshAggregate(supabase, order.produce_listing_id)

  return NextResponse.json({ review })
}

'use client'

import { useState, useEffect } from 'react'
import { useSearchParams } from 'next/navigation'
import { useLang } from '@/lib/LanguageContext'
import StoryTab from './tabs/StoryTab'
import ProduceTab from './tabs/ProduceTab'
import QualityTab from './tabs/QualityTab'
import ReviewsTab from './tabs/ReviewsTab'
import FarmMediaTab from './tabs/FarmMediaTab'
import { CartFab } from '@/components/consumer/Cart'

type Props = {
  farmer: Record<string, unknown>
  produce: Record<string, unknown>[]
  reviews: Record<string, unknown>[]
  media: Record<string, unknown>[]
}

export default function TabSection({ farmer, produce, reviews, media }: Props) {
  const { tx, L } = useLang()
  const [activeTab, setActiveTab] = useState(1)
  const searchParams = useSearchParams()
  const isEditMode = searchParams.get('edit') === 'true'

  const TABS = [tx.story, tx.produce, tx.quality, tx.reviews, tx.farm]

  return (
    <div>
      <div className="sticky top-[53px] z-40 bg-white border-b border-gray-200">
        <div className="flex overflow-x-auto scrollbar-hide">
          {TABS.map((tab, i) => (
            <button
              key={tab}
              onClick={() => setActiveTab(i)}
              className={`flex-shrink-0 px-4 py-3 text-sm font-semibold border-b-2 transition-colors ${
                activeTab === i
                  ? 'border-green-700 text-green-700'
                  : 'border-transparent text-gray-500'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>

      <div className="px-4 py-4">
        {activeTab === 0 && <StoryTab farmer={farmer} />}
        {activeTab === 1 && <ProduceTab farmer={farmer} produce={produce} isEditMode={isEditMode} />}
        {activeTab === 2 && <QualityTab farmer={farmer} produce={produce} />}
        {activeTab === 3 && <ReviewsTab reviews={reviews} farmerId={farmer.id as string} />}
        {activeTab === 4 && <FarmMediaTab media={media} />}
      </div>
      <CartFab />
    </div>
  )
}

'use client'

import { useLang } from '@/lib/LanguageContext'

type Farmer = {
  farming_since_year: number
  rating_avg: number
  buyer_count: number
}

export default function TrustStrip({
  farmer,
  produceCount,
}: {
  farmer: Farmer
  produceCount: number
}) {
  const { tx, L } = useLang()
  const yearsfarming = new Date().getFullYear() - farmer.farming_since_year

  const stats = [
    { label: tx.yearsFarming, value: yearsfarming.toString() },
    { label: tx.starRating, value: `${farmer.rating_avg} ★` },
    { label: tx.buyers, value: farmer.buyer_count.toString() },
    { label: tx.chemicals, value: '0' },
    { label: tx.produceNow, value: `${produceCount}` },
  ]

  return (
    <div className="bg-white border-b border-gray-100">
      <div className="grid grid-cols-5 divide-x divide-gray-100">
        {stats.map((stat) => (
          <div key={stat.label} className="flex flex-col items-center py-3 px-1">
            <span className="text-base font-extrabold text-gray-900">{stat.value}</span>
            <span className="text-[11px] text-gray-500 text-center leading-tight mt-0.5">
              {stat.label}
            </span>
          </div>
        ))}
      </div>
    </div>
  )
}

